<?php include '../auth/cek_login.php';include '../koneksi.php';$q=mysqli_query($conn,'SELECT t.*,p.nama nama_pelanggan,m.merk,m.tipe,m.nomor_polisi FROM transaksi t JOIN pelanggan p ON t.id_pelanggan=p.id JOIN mobil m ON t.id_mobil=m.id ORDER BY t.id DESC');?><!doctype html><html><head><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Transaksi Penyewaan</h1><a class="btn" href="tambah.php">+ Transaksi Baru</a> <a class="btn" href="../dashboard.php">Dashboard</a><br><br><table><tr><th>Kode</th><th>Pelanggan</th><th>Mobil</th><th>Tanggal</th><th>Total</th><th>Status</th></tr><?php while($t=mysqli_fetch_assoc($q)):?><tr><td><?=$t['kode_transaksi']?></td><td><?=$t['nama_pelanggan']?></td><td><?=$t['merk']?> <?=$t['tipe']?> <?=$t['nomor_polisi']?></td><td><?=$t['tanggal_sewa']?></td><td>Rp <?=number_format($t['total_harga'],0,',','.')?></td><td><?=$t['status']?></td></tr><?php endwhile;?></table></div></body></html>
